30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.PetType;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.repository.OwnerRepository;
34	import org.springframework.samples.petclinic.util.EntityUtils;
35	import org.springframework.stereotype.Repository;
36	
37	import javax.sql.DataSource;
38	import jakarta.transaction.Transactional;
39	import java.time.LocalDate;
40	import java.util.Collection;
41	import java.util.HashMap;
42	import java.util.List;
43	import java.util.Map;
44	
45	/**
46	 * A simple JDBC-based implementation of the {@link OwnerRepository} interface.
47	 *
48	 * @author Ken Krebs
49	 * @author Juergen Hoeller
50	 * @author Rob Harrop
51	 * @author Sam Brannen
52	 * @author Thomas Risberg
53	 * @author Mark Fisher
54	 * @author Antoine Rey
55	 * @author Vitaliy Fedoriv
56	 */
57	@DependsOnDatabaseInitialization
58	@Repository
59	@Profile("jdbc")
60	public class JdbcOwnerRepositoryImpl implements OwnerRepository {
61	
62	    private NamedParameterJdbcTemplate namedParameterJdbcTemplate;
63	
64	    private SimpleJdbcInsert insertOwner;
65	
66	    public JdbcOwnerRepositoryImpl(DataSource dataSource) {
67	
68	        this.insertOwner = new SimpleJdbcInsert(dataSource)
69	            .withTableName("owners")
70	            .usingGeneratedKeyColumns("id");
71	
72	        this.namedParameterJdbcTemplate = new NamedParameterJdbcTemplate(dataSource);
73	
74	    }
75	
76	
77	    /**
78	     * Loads {@link Owner Owners} from the data store by last name, returning all owners whose last name <i>starts</i> with
79	     * the given name; also loads the {@link Pet Pets} and {@link Visit Visits} for the corresponding owners, if not
80	     * already loaded.
81	     */
82	    @Override
83	    public Collection<Owner> findByLastName(String lastName) throws DataAccessException {
84	        Map<String, Object> params = new HashMap<>();
85	        params.put("lastName", lastName + "%");
86	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
87	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName",
88	            params,
89	            BeanPropertyRowMapper.newInstance(Owner.class)
90	        );
91	        loadOwnersPetsAndVisits(owners);
92	        return owners;
93	    }
94	
95	    @Override
96	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
97	        Map<String, Object> params = new HashMap<>();
98	        params.put("lastName", lastName + "%");
99	        params.put("size", pageable.getPageSize());
100	        params.put("offset", pageable.getOffset());
101	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
102	            "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE last_name like :lastName ORDER BY id LIMIT :size OFFSET :offset",
103	            params,
104	            BeanPropertyRowMapper.newInstance(Owner.class)
105	        );
106	        loadOwnersPetsAndVisits(owners);
107	        Long total = this.namedParameterJdbcTemplate.queryForObject(
108	            "SELECT COUNT(*) FROM owners WHERE last_name like :lastName",
109	            params,
110	            Long.class
111	        );
112	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
113	    }
114	
115	    /**
116	     * Loads the {@link Owner} with the supplied <code>id</code>; also loads the {@link Pet Pets} and {@link Visit Visits}
117	     * for the corresponding owner, if not already loaded.
118	     */
119	    @Override
120	    public Owner findById(int id) throws DataAccessException {
121	        Owner owner;
122	        try {
123	            Map<String, Object> params = new HashMap<>();
124	            params.put("id", id);
125	            owner = this.namedParameterJdbcTemplate.queryForObject(
126	                "SELECT id, first_name, last_name, address, city, telephone FROM owners WHERE id= :id",
127	                params,
128	                BeanPropertyRowMapper.newInstance(Owner.class)
129	            );
130	        } catch (EmptyResultDataAccessException ex) {
131	            throw new ObjectRetrievalFailureException(Owner.class, id);
132	        }
133	        loadPetsAndVisits(owner);
134	        return owner;
135	    }
136	
137	    public void loadPetsAndVisits(final Owner owner) {
138	        Map<String, Object> params = new HashMap<>();
139	        params.put("id", owner.getId());
140	        final List<JdbcPet> pets = this.namedParameterJdbcTemplate.query(
141	            "SELECT pets.id as pets_id, name, birth_date, type_id, owner_id, visits.id as visit_id, visit_date, description, visits.pet_id as visits_pet_id FROM pets LEFT OUTER JOIN visits ON pets.id = visits.pet_id WHERE owner_id=:id ORDER BY pets.id",
142	            params,
143	            new JdbcPetVisitExtractor()
144	        );
145	        Collection<PetType> petTypes = getPetTypes();
146	        for (JdbcPet pet : pets) {
147	            pet.setType(EntityUtils.getById(petTypes, PetType.class, pet.getTypeId()));
148	            owner.addPet(pet);
149	        }
150	    }
151	
152	    @Override
153	    public boolean existsByTelephone(String telephone) throws DataAccessException {
154	        Map<String, Object> params = new HashMap<>();
155	        params.put("telephone", telephone);
156	        Long count = this.namedParameterJdbcTemplate.queryForObject(
157	            "SELECT COUNT(*) FROM owners WHERE telephone = :telephone",
158	            params,
159	            Long.class);
160	        return count != null && count > 0;
161	    }
162	
163	    @Override
164	    public long count() throws DataAccessException {
165	        Long count = this.namedParameterJdbcTemplate.queryForObject(
166	            "SELECT COUNT(*) FROM owners",
167	            new HashMap<String, Object>(),
168	            Long.class);
169	        return count == null ? 0 : count;
170	    }
171	
172	    @Override
173	    public long countByCity(String city) throws DataAccessException {
174	        Map<String, Object> params = new HashMap<>();
175	        params.put("city", city);
176	        Long count = this.namedParameterJdbcTemplate.queryForObject(
177	            "SELECT COUNT(*) FROM owners WHERE city = :city",
178	            params,
179	            Long.class);
180	        return count == null ? 0 : count;
181	    }
182	
183	    @Override
184	    public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
185	        Map<String, Object> params = new HashMap<>();
186	        params.put("registrationDate", registrationDate);
187	        Long count = this.namedParameterJdbcTemplate.queryForObject(
188	            "SELECT COUNT(*) FROM owners WHERE registration_date = :registrationDate",
189	            params,
190	            Long.class);
191	        return count == null ? 0 : count;
192	    }
193	
194	    @Override
195	    public void save(Owner owner) throws DataAccessException {
196	        BeanPropertySqlParameterSource parameterSource = new BeanPropertySqlParameterSource(owner);
197	        if (owner.isNew()) {
198	            Number newKey = this.insertOwner.executeAndReturnKey(parameterSource);
199	            owner.setId(newKey.intValue());
200	        } else {
201	            this.namedParameterJdbcTemplate.update(
202	                "UPDATE owners SET first_name=:firstName, last_name=:lastName, address=:address, " +
203	                    "city=:city, telephone=:telephone WHERE id=:id",
204	                parameterSource);
205	        }
206	    }
207	
208	    public Collection<PetType> getPetTypes() throws DataAccessException {
209	        return this.namedParameterJdbcTemplate.query(
210	            "SELECT id, name FROM types ORDER BY name", new HashMap<String, Object>(),
211	            BeanPropertyRowMapper.newInstance(PetType.class));
212	    }
213	
214	    /**
215	     * Loads the {@link Pet} and {@link Visit} data for the supplied {@link List} of {@link Owner Owners}.
216	     *
217	     * @param owners the list of owners for whom the pet and visit data should be loaded
218	     * @see #loadPetsAndVisits(Owner)
219	     */
220	    private void loadOwnersPetsAndVisits(List<Owner> owners) {
221	        for (Owner owner : owners) {
222	            loadPetsAndVisits(owner);
223	        }
224	    }
225	
226		@Override
227		public Collection<Owner> findAll() throws DataAccessException {
228			List<Owner> owners = this.namedParameterJdbcTemplate.query(
229		            "SELECT id, first_name, last_name, address, city, telephone FROM owners",
230		            new HashMap<String, Object>(),
231		            BeanPropertyRowMapper.newInstance(Owner.class));
232			for (Owner owner : owners) {
233	            loadPetsAndVisits(owner);
234	        }
235		    return owners;
236		}
237	
238	    @Override
239	    public Page<Owner> findAll(Pageable pageable) throws DataAccessException {
240	        Map<String, Object> params = new HashMap<>();
241	        params.put("size", pageable.getPageSize());
242	        params.put("offset", pageable.getOffset());
243	        List<Owner> owners = this.namedParameterJdbcTemplate.query(
244	            "SELECT id, first_name, last_name, address, city, telephone FROM owners ORDER BY id LIMIT :size OFFSET :offset",
245	            params,
246	            BeanPropertyRowMapper.newInstance(Owner.class));
247	        loadOwnersPetsAndVisits(owners);
248	        Long total = this.namedParameterJdbcTemplate.queryForObject(
249	            "SELECT COUNT(*) FROM owners",
250	            params,
251	            Long.class
252	        );
253	        return new PageImpl<>(owners, pageable, total == null ? 0 : total);
254	    }
255	
256		@Override
257		@Transactional
258		public void delete(Owner owner) throws DataAccessException {
259			Map<String, Object> ownerParams = new HashMap<>();
260			ownerParams.put("id", owner.getId());
261	        List<Pet> pets = owner.getPets();
262	        // cascade delete pets
263	        for (Pet pet : pets){
264	        	Map<String, Object> petParams = new HashMap<>();
265	        	petParams.put("id", pet.getId());
266	        	// cascade delete visits
267	        	List<Visit> visits = pet.getVisits();
268	            for (Visit visit : visits){
269	            	Map<String, Object> visitParams = new HashMap<>();
270	            	visitParams.put("id", visit.getId());
271	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
272	            }
273	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
274	        }
275	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
276		}
277	
278	
279	}
